CREATE TABLE IF NOT EXISTS migrations (name VARCHAR(191) PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id, permission_id));
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id, role_id));
CREATE TABLE IF NOT EXISTS languages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, locale VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, native_name VARCHAR(80) NOT NULL, enabled TINYINT(1) NOT NULL DEFAULT 1, is_default TINYINT(1) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(191) PRIMARY KEY, value JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS installed_themes (slug VARCHAR(100) PRIMARY KEY, version VARCHAR(30) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 0, settings JSON NULL, installed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS installed_plugins (slug VARCHAR(100) PRIMARY KEY, version VARCHAR(30) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 0, settings JSON NULL, installed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id BIGINT UNSIGNED NULL, template VARCHAR(100) NULL, featured_media_id BIGINT UNSIGNED NULL, status ENUM('draft','published','private','scheduled','archived') NOT NULL DEFAULT 'draft', visibility ENUM('public','private') NOT NULL DEFAULT 'public', sort_order INT NOT NULL DEFAULT 0, published_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX(status), INDEX(parent_id));
CREATE TABLE IF NOT EXISTS page_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL, excerpt TEXT NULL, seo_title VARCHAR(255) NULL, seo_description TEXT NULL, canonical_url VARCHAR(500) NULL, robots VARCHAR(100) NULL, UNIQUE KEY page_locale(page_id, locale), UNIQUE KEY locale_slug(locale, slug));
CREATE TABLE IF NOT EXISTS content_blocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, type VARCHAR(80) NOT NULL, visible TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX(page_id));
CREATE TABLE IF NOT EXISTS content_block_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, block_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, data JSON NOT NULL, UNIQUE KEY block_locale(block_id, locale));
CREATE TABLE IF NOT EXISTS menus (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, location VARCHAR(100) NOT NULL UNIQUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS menu_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, page_id BIGINT UNSIGNED NULL, type ENUM('page','url') NOT NULL DEFAULT 'url', label VARCHAR(120) NULL, url VARCHAR(500) NULL, target VARCHAR(20) NOT NULL DEFAULT '_self', visible TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, INDEX(menu_id));
CREATE TABLE IF NOT EXISTS menu_item_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, menu_item_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, label VARCHAR(120) NOT NULL, url VARCHAR(500) NOT NULL, UNIQUE KEY menu_locale(menu_item_id, locale));
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path VARCHAR(500) NOT NULL, mime_type VARCHAR(100) NOT NULL, original_name VARCHAR(255) NOT NULL, alt_text VARCHAR(255) NULL, caption TEXT NULL, width INT NULL, height INT NULL, size_bytes BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(150) NOT NULL UNIQUE, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, author_id BIGINT UNSIGNED NULL, category_id BIGINT UNSIGNED NULL, featured_media_id BIGINT UNSIGNED NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', published_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS post_translations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, post_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL, excerpt TEXT NULL, content LONGTEXT NULL, seo_title VARCHAR(255) NULL, seo_description TEXT NULL, UNIQUE KEY post_locale(post_id, locale), UNIQUE KEY post_slug(locale, slug));
CREATE TABLE IF NOT EXISTS forms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, schema_json JSON NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS form_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, form_id BIGINT UNSIGNED NOT NULL, payload JSON NOT NULL, status VARCHAR(50) NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL, INDEX(form_id));
CREATE TABLE IF NOT EXISTS activity_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, event VARCHAR(100) NOT NULL, subject_type VARCHAR(100) NULL, subject_id BIGINT UNSIGNED NULL, context JSON NULL, created_at DATETIME NOT NULL, INDEX(event), INDEX(user_id));
